function Pump([int]$ms){$f=New-Object Windows.Threading.DispatcherFrame;$t=New-Object Windows.Threading.DispatcherTimer;$t.Interval=[TimeSpan]::FromMilliseconds($ms);$t.Add_Tick({$t.Stop();$f.Continue=$false});$t.Start();[Windows.Threading.Dispatcher]::PushFrame($f)}
function Shot([string]$path){$window.UpdateLayout();$a=$window.PointToScreen([Windows.Point]::new(0,0));$b=$window.PointToScreen([Windows.Point]::new($window.ActualWidth,$window.ActualHeight));$w=[Math]::Max(1,[int][Math]::Ceiling($b.X-$a.X));$h=[Math]::Max(1,[int][Math]::Ceiling($b.Y-$a.Y));$bmp=[Drawing.Bitmap]::new($w,$h);$g=[Drawing.Graphics]::FromImage($bmp);$saved=$false;try{$g.CopyFromScreen([int]$a.X,[int]$a.Y,0,0,[Drawing.Size]::new($w,$h));$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png);$saved=$true}catch{$saved=$false}finally{$g.Dispose();$bmp.Dispose()};if(-not$saved){$render=[Activator]::CreateInstance([Windows.Media.Imaging.RenderTargetBitmap],[object[]]@($w,$h,96.0,96.0,[Windows.Media.PixelFormats]::Pbgra32));$render.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($render));$stream=[IO.File]::Open($path,[IO.FileMode]::Create,[IO.FileAccess]::Write);try{$encoder.Save($stream)}finally{$stream.Dispose()}};"${w}x${h}"}
