function Pattern([string]$path){$w=640;$h=440;$head=[Text.Encoding]::ASCII.GetBytes("P5`n$w $h`n255`n");$px=New-Object byte[]($w*$h);for($r=0;$r-lt$h;$r++){for($c=0;$c-lt$w;$c++){$v=25+[int](55*$c/$w);if($r-gt65-and$r-lt195-and$c-gt85-and$c-lt305){$v=222};if($r-gt250-and$r-lt390-and$c-gt350-and$c-lt585){$v=150};if(($r-130)*($r-130)+($c-505)*($c-505)-lt55*55){$v=250};$px[$r*$w+$c]=[byte]$v}};$data=New-Object byte[]($head.Length+$px.Length);[Array]::Copy($head,0,$data,0,$head.Length);[Array]::Copy($px,0,$data,$head.Length,$px.Length);[IO.File]::WriteAllBytes($path,$data)}
